'use client';

import { FormischEngine } from '../auto-form/adapters/formisch';
import { type FormischAutoFormApi, objectStorage } from '../auto-form/adapters/formisch-storage';
import { AutoFormCore } from '../auto-form/auto-form-core';
import { shadcnUIComponents } from '../auto-form/shadcn-ui-components';
import type { AutoFormProps as BaseAutoFormProps } from '../auto-form/types';

type FormValues = Record<string, unknown>;

export type AutoFormProps<T extends FormValues = FormValues, TCustomFieldType extends string = never> = Omit<
  BaseAutoFormProps<T, FormischAutoFormApi, never, never, TCustomFieldType>,
  'formOptions' | 'resolver'
>;

export type { FormischAutoFormApi } from '../auto-form/adapters/formisch-storage';
export { useAutoForm } from '../auto-form/context';
export type { AutoFormSubmitContext } from '../auto-form/types';

export function AutoForm<T extends FormValues = FormValues, TCustomFieldType extends string = never>({
  components = shadcnUIComponents,
  ...props
}: AutoFormProps<T, TCustomFieldType>) {
  return (
    <AutoFormCore<T, FormischAutoFormApi, TCustomFieldType>
      {...props}
      components={components}
      renderEngine={({ children, defaultValues, parsedSchema, values }) => {
        const storage = objectStorage(parsedSchema.fields);
        return (
          <FormischEngine
            defaultValues={defaultValues}
            key={JSON.stringify(storage)}
            onDirtyChange={props.onDirtyChange}
            storage={storage}
            values={values}
          >
            {children}
          </FormischEngine>
        );
      }}
    />
  );
}

'use client';

import {
  getDeepErrorEntries,
  getInput,
  handleSubmit,
  type RequiredPath,
  reset,
  setErrors,
  setInput,
  useForm,
} from '@formisch/react';
import React from 'react';
import { dirtyFieldsFromValues } from '@/registry/base-nova/protoform/lib/protobuf-provider/field-mask';
import { PROTO_FORM_ROOT_ERROR_KEY } from '@/registry/base-nova/protoform/lib/protobuf-provider/hook-runtime';
import type { SchemaValidationError } from '../core-types';
import {
  type AutoFormArrayController,
  type AutoFormEngine,
  AutoFormEngineProvider,
  type AutoFormFieldController,
  useAutoFormEngine,
  useDirtyStateNotification,
} from '../engine';
import { getPathInObject } from '../field-utils';
import { getFieldErrorMessage } from '../helpers';
import {
  clearFieldError,
  errorTree,
  type FormischAutoFormApi,
  insertGeneratedItem,
  objectSchema,
  type objectStorage,
  removeGeneratedItem,
  setGeneratedValue,
  storagePath,
  useGeneratedArrayKeys,
} from './formisch-storage';

type Values = Record<string, unknown>;
interface FieldProps {
  children: (controller: AutoFormFieldController) => React.ReactNode;
  name: string;
}
interface ArrayProps {
  children: (controller: AutoFormArrayController) => React.ReactNode;
  name: string;
}

const FormischContext = React.createContext<{
  form: FormischAutoFormApi;
  storage: ReturnType<typeof objectStorage>;
  registerRef: (path: string, element: HTMLElement | null) => void;
} | null>(null);

function useFormischContext() {
  const context = React.useContext(FormischContext);
  if (context === null) {
    throw new Error('Formisch controls must be rendered inside the Formisch engine.');
  }
  return context;
}

function FormischFieldController({ children, name }: FieldProps) {
  const engine = useAutoFormEngine();
  const { registerRef } = useFormischContext();
  const path = name.split('.');
  const error = getFieldErrorMessage(engine.errors, path);
  return children({
    errors: error?.split('\n') ?? [],
    name,
    onBlur: () => undefined,
    onChange: (value, options) => engine.setValue(name, value, options),
    ref: (element) => registerRef(name, element),
    value: getPathInObject(engine.values, path),
  });
}

function NativeArrayController({ children, name, path }: ArrayProps & { path: RequiredPath }) {
  'use no memo';
  const { form } = useFormischContext();
  const engine = useAutoFormEngine();
  const keys = useGeneratedArrayKeys(form, path);
  const input = getPathInObject(engine.values, name.split('.'));
  const values: unknown[] = Array.isArray(input) ? input : [];
  return children({
    append: (value) => {
      engine.clearErrors([name]);
      insertGeneratedItem(form, path, value);
    },
    items: keys.map((key, index) => ({ key, value: values[index] })),
    remove: (index) => {
      engine.clearErrors([name]);
      removeGeneratedItem(form, path, index);
    },
  });
}

function AtomicArrayController({ children, name }: ArrayProps) {
  const engine = useAutoFormEngine();
  const input = getPathInObject(engine.values, name.split('.'));
  const values: unknown[] = Array.isArray(input) ? input : [];
  const [keyState, setKeyState] = React.useState(() => ({
    keys: values.map((_, index) => index),
    next: values.length,
  }));
  const nextKeys = keyState.keys.slice(0, values.length);
  let nextId = keyState.next;
  if (keyState.keys.length !== values.length) {
    while (nextKeys.length < values.length) {
      nextKeys.push(nextId);
      nextId += 1;
    }
    setKeyState({ keys: nextKeys, next: nextId });
  }
  return children({
    append: (value) => {
      setKeyState({ keys: [...nextKeys, nextId], next: nextId + 1 });
      engine.setValue(name, [...values, value]);
    },
    items: nextKeys.map((key, index) => ({ key: String(key), value: values[index] })),
    remove: (index) => {
      setKeyState({ keys: nextKeys.filter((_, itemIndex) => index !== itemIndex), next: nextId });
      engine.setValue(
        name,
        values.filter((_, itemIndex) => index !== itemIndex)
      );
    },
  });
}

function FormischArrayController(props: ArrayProps) {
  const { storage } = useFormischContext();
  const path = storagePath(storage, props.name);
  return path?.storage.kind === 'array' && path.remaining.length === 0 ? (
    <NativeArrayController {...props} path={path.field} />
  ) : (
    <AtomicArrayController {...props} />
  );
}

function includesPath(name: string, paths: string[]) {
  return paths.some((path) => path === name || name.startsWith(`${path}.`));
}

function includesRoot(paths: string[]) {
  return paths.includes('root') || paths.includes(PROTO_FORM_ROOT_ERROR_KEY);
}

function useFieldFocus() {
  const fieldMapRef = React.useRef(new Map<string, HTMLElement>());
  const focus = React.useCallback((path: string) => fieldMapRef.current.get(path)?.focus(), []);
  const registerRef = React.useCallback((path: string, element: HTMLElement | null) => {
    if (element) {
      fieldMapRef.current.set(path, element);
    } else {
      fieldMapRef.current.delete(path);
    }
  }, []);
  return { focus, registerRef };
}

interface FormischEngineProps {
  children: (engine: AutoFormEngine) => React.ReactNode;
  defaultValues: Values;
  onDirtyChange?: ((isDirty: boolean) => void) | undefined;
  storage: ReturnType<typeof objectStorage>;
  values?: Values | undefined;
}

export function FormischEngine({ children, defaultValues, onDirtyChange, storage, values }: FormischEngineProps) {
  'use no memo';

  const schema = React.useMemo(() => objectSchema(storage), [storage]);
  const form = useForm({ initialInput: values ?? defaultValues, revalidate: 'submit', schema });
  const input = getInput(form);
  const [cleanValues, setCleanValues] = React.useState(input);
  const [snapshot, setSnapshot] = React.useState(input);
  const [providerErrors, setProviderErrors] = React.useState<SchemaValidationError[]>([]);
  const [seenValues, setSeenValues] = React.useState(values);
  const { focus, registerRef } = useFieldFocus();
  if (values !== seenValues) {
    setSeenValues(values);
    if (values) {
      setCleanValues(values);
      setProviderErrors([]);
    }
  }
  const hasNewInput = Object.keys(dirtyFieldsFromValues(input, snapshot)).length > 0;
  if (hasNewInput) {
    setSnapshot(input);
  }
  const currentValues = hasNewInput ? input : snapshot;

  const dirtyFields = dirtyFieldsFromValues(currentValues, cleanValues);
  const isDirty = Object.keys(dirtyFields).length > 0;
  const notifyDirty = useDirtyStateNotification(isDirty, onDirtyChange);
  const nativeErrors = getDeepErrorEntries(form);
  const issues = [
    ...providerErrors,
    ...nativeErrors.flatMap(({ path, errors: messages }) => messages.map((message) => ({ message, path: [...path] }))),
  ];
  const errors = new Map<string, string[]>();
  for (const issue of issues) {
    const name = issue.path.join('.');
    const previous = errors.get(name) ?? [];
    if (!previous.includes(issue.message)) {
      errors.set(name, [...previous, issue.message]);
    }
  }

  React.useEffect(() => {
    if (values) {
      reset(form, { initialInput: values });
    }
  }, [form, values]);

  const clearErrors = (paths?: string[]) => {
    if (!paths || includesRoot(paths)) {
      setErrors(form, { errors: null });
    }
    for (const { path } of getDeepErrorEntries(form)) {
      const [first, ...rest] = path;
      if (first !== undefined && (!paths || includesPath(path.join('.'), paths))) {
        clearFieldError(form, [first, ...rest]);
      }
    }
    setProviderErrors((current) =>
      paths
        ? current.filter(({ path }) =>
            path.length === 0 ? !includesRoot(paths) : !includesPath(path.join('.'), paths)
          )
        : []
    );
  };

  const engine: AutoFormEngine = {
    ArrayController: FormischArrayController,
    clearErrors,
    defaultValues: cleanValues,
    dirtyFields,
    errors: errorTree(issues),
    FieldController: FormischFieldController,
    focus,
    getFieldInvalid: (path) => [...errors.keys()].some((name) => includesPath(name, [path])),
    getValues: () => getInput(form),
    handleSubmit: (onValid) => (event) => {
      event.preventDefault();
      if (form.isSubmitting) {
        return;
      }
      handleSubmit(form, onValid)().catch((error: unknown) => {
        setErrors(form, { errors: [error instanceof Error ? error.message : 'Submission failed.'] });
      });
    },
    isDirty,
    isSubmitting: form.isSubmitting,
    markClean: () => {
      reset(form, { initialInput: getInput(form) });
      setCleanValues(getInput(form));
      setProviderErrors([]);
      notifyDirty(false);
    },
    nativeForm: form,
    reset: (nextValues, options) => {
      if (options?.keepDefaultValues) {
        reset(form);
        setInput(form, { input: nextValues });
      } else {
        reset(form, { initialInput: nextValues });
        setCleanValues(getInput(form));
      }
      setProviderErrors([]);
    },
    rootError: errors.get('')?.join('\n'),
    setRootError: (message) => setErrors(form, { errors: [message] }),
    setValidationErrors: setProviderErrors,
    setValue: (path, value) => {
      clearErrors([path]);
      setGeneratedValue(form, storage, path, value);
    },
    trigger: (paths) =>
      Promise.resolve(
        getDeepErrorEntries(form).every(({ path }) => paths !== undefined && !includesPath(path.join('.'), paths))
      ),
    validatesSchema: false,
    values: currentValues,
  };

  const context = React.useMemo(() => ({ form, registerRef, storage }), [form, registerRef, storage]);
  return (
    <FormischContext.Provider value={context}>
      <AutoFormEngineProvider engine={engine}>{children(engine)}</AutoFormEngineProvider>
    </FormischContext.Provider>
  );
}

import type { FormStore, RequiredPath } from '@formisch/react';
import { getInput, insert, remove, setErrors, setInput, useFieldArray } from '@formisch/react';
import { array, type GenericSchema, nullish, object, unknown as unknownValue } from 'valibot';
import type { ParsedField } from '../core-types';

type Values = Record<string, unknown>;
type Segment = string | number;
const ARRAY_INDEX = /^\d+$/u;
type Storage =
  | { kind: 'leaf' }
  | { kind: 'array'; item: Storage }
  | { kind: 'object'; entries: Record<string, Storage> };

function fieldStorage(field: ParsedField): Storage {
  if (field.type === 'object' && field.schema) {
    return objectStorage(field.schema);
  }
  if (field.type === 'array' && field.schema?.[0]) {
    return { item: fieldStorage(field.schema[0]), kind: 'array' };
  }
  if (field.type === 'map' && field.schema) {
    return { item: objectStorage(field.schema), kind: 'array' };
  }
  if (field.type === 'oneof') {
    return { entries: { case: { kind: 'leaf' }, value: { kind: 'leaf' } }, kind: 'object' };
  }
  return { kind: 'leaf' };
}

export function objectStorage(fields: ParsedField[]): Extract<Storage, { kind: 'object' }> {
  return {
    entries: Object.fromEntries(
      fields.map((field) => {
        if (Object.hasOwn(Object.prototype, field.key)) {
          throw new Error(`Formisch cannot register the field "${field.key}".`);
        }
        return [field.key, fieldStorage(field)];
      })
    ),
    kind: 'object',
  };
}

function storageSchema(storage: Storage): GenericSchema {
  if (storage.kind === 'object') {
    return nullish(objectSchema(storage));
  }
  if (storage.kind === 'array') {
    return nullish(array(storageSchema(storage.item)));
  }
  return unknownValue();
}

export function objectSchema(storage: Extract<Storage, { kind: 'object' }>) {
  return object(Object.fromEntries(Object.entries(storage.entries).map(([key, node]) => [key, storageSchema(node)])));
}

type GeneratedSchema = ReturnType<typeof objectSchema>;
export type FormischAutoFormApi = FormStore<GeneratedSchema>;

export function storagePath(storage: Storage, name: string) {
  const keys = name.split('.');
  const path: Segment[] = [];
  let current = storage;
  for (const key of keys) {
    if (current.kind === 'leaf') {
      break;
    }
    if (current.kind === 'array') {
      if (!ARRAY_INDEX.test(key)) {
        return;
      }
      path.push(Number(key));
      current = current.item;
    } else {
      const next = Object.hasOwn(current.entries, key) ? current.entries[key] : undefined;
      if (!next) {
        return;
      }
      path.push(key);
      current = next;
    }
  }

  const [first, ...rest] = path;
  if (first === undefined) {
    return;
  }
  const field: RequiredPath = [first, ...rest];
  return { field, remaining: keys.slice(path.length), storage: current };
}

function ownValue(value: unknown, key: Segment): unknown {
  return typeof value === 'object' && value !== null && Object.hasOwn(value, key) ? Reflect.get(value, key) : undefined;
}

function withPathValue(input: unknown, path: string[], value: unknown): unknown {
  const [head, ...rest] = path;
  if (head === undefined) {
    return value;
  }
  const next = withPathValue(ownValue(input, head), rest, value);
  if (Array.isArray(input)) {
    const index = Number(head);
    if (Number.isInteger(index) && index >= 0 && index < input.length) {
      const previousItems: unknown[] = input;
      const items = [...previousItems];
      items[index] = next;
      return items;
    }
  }
  return { ...(typeof input === 'object' && input !== null ? input : {}), [head]: next };
}

function readFieldInput(form: FormischAutoFormApi, path: RequiredPath): unknown {
  return Reflect.apply(getInput, undefined, [form, { path }]);
}

export function clearFieldError(form: FormischAutoFormApi, path: RequiredPath) {
  Reflect.apply(setErrors, undefined, [form, { errors: null, path }]);
}

export function useGeneratedArrayKeys(form: FormischAutoFormApi, path: RequiredPath): string[] {
  const field: unknown = Reflect.apply(useFieldArray, undefined, [form, { path }]);
  const items = ownValue(field, 'items');
  if (!(Array.isArray(items) && items.every((item: unknown): item is string => typeof item === 'string'))) {
    throw new TypeError('Expected native Formisch field-array keys.');
  }
  return items;
}

export function insertGeneratedItem(form: FormischAutoFormApi, path: RequiredPath, initialInput: unknown) {
  Reflect.apply(insert, undefined, [form, { initialInput, path }]);
}

export function removeGeneratedItem(form: FormischAutoFormApi, path: RequiredPath, at: number) {
  Reflect.apply(remove, undefined, [form, { at, path }]);
}

export function setGeneratedValue(form: FormischAutoFormApi, storage: Storage, name: string, value: unknown) {
  const path = storagePath(storage, name);
  if (!path) {
    return;
  }
  const input =
    path.remaining.length > 0 ? withPathValue(readFieldInput(form, path.field), path.remaining, value) : value;
  Reflect.apply(setInput, undefined, [form, { input, path: path.field }]);
}

export function errorTree(issues: Array<{ message: string; path: Segment[] }>): Values {
  const errors: Values = {};
  for (const issue of issues) {
    let current = errors;
    for (const [index, key] of issue.path.entries()) {
      const previous = ownValue(current, key);
      const next: Values = { ...(typeof previous === 'object' && previous !== null ? previous : {}) };
      if (index === issue.path.length - 1) {
        const { message } = next;
        next['message'] = typeof message === 'string' ? `${message}\n${issue.message}` : issue.message;
      }
      Object.defineProperty(current, key, { configurable: true, enumerable: true, value: next });
      current = next;
    }
  }
  return errors;
}

import React from 'react';
